function makeSackWall(length = 5) {
  const group = new THREE.Group();
  const count = Math.ceil(length / 0.66);
  for (let i = 0; i < count; i++) {
    const bag = addBox(group, 0.64, 0.27, 0.64, M.sand, -length / 2 + i * 0.66, 0.16, 0);
    bag.rotation.y = (i % 2 ? 1 : -1) * 0.06;
    if (i % 3 === 1) {
      const bag2 = addBox(group, 0.58, 0.25, 0.6, M.sand, -length / 2 + i * 0.66 + 0.15, 0.42, 0.04);
      bag2.rotation.y = 0.1;
    }
  }
  return group;
}

function makeCrate(size = 0.8) {
  const group = new THREE.Group();
  addBox(group, size, size * 0.72, size, M.sand, 0, size * 0.36, 0);
  addBox(group, size * 0.92, size * 0.08, size * 1.01, M.oliveDark, 0, size * 0.53, 0, false);
  addBox(group, size * 0.08, size * 0.7, size * 1.01, M.oliveDark, 0, size * 0.36, 0, false);
  return group;
}

function makeBarrel() {
  const group = new THREE.Group();
  const barrel = addCyl(group, 0.23, 0.25, 0.78, 10, M.redDark, 0, 0.39, 0);
  addCyl(group, 0.255, 0.255, 0.05, 10, M.gunmetal, 0, 0.18, 0, false);
  addCyl(group, 0.255, 0.255, 0.05, 10, M.gunmetal, 0, 0.6, 0, false);
  return group;
}

function makeTree(scale = 1, tone = 0) {
  const group = new THREE.Group();
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x51432f, roughness: 1, flatShading: true });
  const leafMat = new THREE.MeshStandardMaterial({
    color: [0x59603d, 0x6a6c42, 0x4b573a][tone % 3],
    roughness: 1,
    flatShading: true,
  });
  addCyl(group, 0.08, 0.13, 1.4 * scale, 5, trunkMat, 0, 0.7 * scale, 0);
  for (let i = 0; i < 3; i++) {
    const blob = addSphere(group, (0.52 - i * 0.08) * scale, leafMat, (i % 2 ? 0.18 : -0.12) * scale, (1.45 + i * 0.28) * scale, (i === 1 ? 0.14 : -0.08) * scale, 6, 5);
    blob.scale.y = 0.82;
    blob.castShadow = true;
  }
  return group;
}

function makeRock(scale = 1) {
  const rock = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: 0x7d7665, roughness: 1, flatShading: true });
  const mesh = addSphere(rock, 0.7 * scale, mat, 0, 0.3 * scale, 0, 5, 4);
  mesh.scale.set(1.3, 0.75, 1.05);
  const chip = addSphere(rock, 0.28 * scale, mat, 0.52 * scale, 0.18 * scale, 0.24 * scale, 4, 3);
  chip.scale.y = 0.7;
  return rock;
}

function makeBush(scale = 1) {
  const group = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ color: 0x62653f, roughness: 1, flatShading: true });
  for (let i = 0; i < 3; i++) {
    const blob = addSphere(group, 0.22 * scale, mat, (i - 1) * 0.2 * scale, 0.16 * scale, (i % 2) * 0.14 * scale, 5, 4);
    blob.scale.y = 0.55;
  }
  return group;
}

function makeTankTrap() {
  const group = new THREE.Group();
  for (let i = 0; i < 3; i++) {
    const beam = addBox(group, 1.1, 0.09, 0.09, M.gunmetal, 0, 0.36, 0);
    beam.rotation.z = 0.6;
    beam.rotation.y = (i / 3) * Math.PI;
  }
  return group;
}

function makeMarkerRing(color = 0xc9ff54) {
  const group = new THREE.Group();
  const outer = new THREE.Mesh(
    new THREE.RingGeometry(0.75, 0.88, 32),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false })
  );
  const inner = new THREE.Mesh(
    new THREE.RingGeometry(0.2, 0.27, 20),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.7, side: THREE.DoubleSide, depthWrite: false })
  );
  group.add(outer, inner);
  group.userData.outer = outer;
  group.userData.inner = inner;
  return group;
}

export {
  M,
  TEAM_COLORS,
  addBox,
  addCyl,
  addSphere,
  addMuzzle,
  makeSoldier,
  makeHumvee,
  makeTank,
  makeArtillery,
  makeFighter,
  makeBase,
  makeWatchtower,
  makeSackWall,
  makeCrate,
  makeBarrel,
  makeTree,
  makeRock,
  makeBush,
  makeTankTrap,
  makeMarkerRing,
};

/* Tiny procedural battlefield audio engine. No external assets or network. */
export class SoundSystem {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.compressor = null;
    this.noiseBuffer = null;
    this.muted = false;
    this.volume = 0.72;
    this.last = new Map();
  }

  async unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : this.volume;
    this.compressor = this.ctx.createDynamicsCompressor();
    this.compressor.threshold.value = -18;
    this.compressor.knee.value = 18;
    this.compressor.ratio.value = 5;
    this.compressor.attack.value = 0.004;
    this.compressor.release.value = 0.3;
    this.master.connect(this.compressor);
    this.compressor.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise(2.5);
    this.startAmbience();
    if (this.ctx.state === 'suspended') await this.ctx.resume();
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    let brown = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      brown = (brown + 0.018 * white) / 1.018;
      data[i] = white * 0.58 + brown * 2.1;
    }
    return buf;
  }

  startAmbience() {
    const ctx = this.ctx;
    const bus = ctx.createGain();
    bus.gain.value = 0.5;
    bus.connect(this.master);

    const wind = ctx.createBufferSource();
    wind.buffer = this.noiseBuffer;
    wind.loop = true;
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'bandpass';
    windFilter.frequency.value = 420;
    windFilter.Q.value = 0.4;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.022;
    wind.connect(windFilter).connect(windGain).connect(bus);

    const rumble = ctx.createBufferSource();
    rumble.buffer = this.noiseBuffer;
    rumble.loop = true;
    const rumbleFilter = ctx.createBiquadFilter();
    rumbleFilter.type = 'lowpass';
    rumbleFilter.frequency.value = 85;
    const rumbleGain = ctx.createGain();
    rumbleGain.gain.value = 0.06;
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 0.018;
    lfo.connect(lfoGain).connect(rumbleGain.gain);
    rumble.connect(rumbleFilter).connect(rumbleGain).connect(bus);

    for (const [freq, gain] of [[46, 0.011], [69, 0.007], [93, 0.004]]) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq;
      const g = ctx.createGain();
      g.gain.value = gain;
      const drift = ctx.createOscillator();
      const driftGain = ctx.createGain();
      drift.frequency.value = 0.03 + Math.random() * 0.03;
      driftGain.gain.value = gain * 0.5;
      drift.connect(driftGain).connect(g.gain);
      osc.connect(g).connect(bus);
      drift.start();
      osc.start();
    }

    wind.start();
    rumble.start();
    lfo.start();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : this.volume, this.ctx.currentTime + 0.12);
    }
  }

  setVolume(volume) {
    this.volume = Math.max(0, Math.min(1, volume));
    if (this.master && !this.muted) this.master.gain.value = this.volume;
  }

  throttled(key, ms) {
    const now = performance.now();
    if ((this.last.get(key) || 0) + ms > now) return true;
    this.last.set(key, now);
    return false;
  }

  noiseBurst({ duration = 0.12, gain = 0.1, type = 'lowpass', freq = 900, q = 0.7, pan = 0, when = 0, sweep = 0 }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = 0.85 + Math.random() * 0.3;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    if (sweep) filter.frequency.exponentialRampToValueAtTime(Math.max(40, freq + sweep), t + duration);
    filter.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    const p = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    if (p) {
      p.pan.value = Math.max(-0.8, Math.min(0.8, pan));
      src.connect(filter).connect(g).connect(p).connect(this.master);
    } else {
      src.connect(filter).connect(g).connect(this.master);
    }
    src.start(t, Math.random() * 1.4);
    src.stop(t + duration + 0.03);
  }

  tone({ freq = 220, endFreq = 80, duration = 0.2, gain = 0.08, type = 'sine', pan = 0, when = 0 }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + when;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    const p = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
    if (p) {
      p.pan.value = Math.max(-0.8, Math.min(0.8, pan));
      osc.connect(g).connect(p).connect(this.master);
    } else {
      osc.connect(g).connect(this.master);
    }
    osc.start(t);
    osc.stop(t + duration + 0.02);
  }

  rifle(pan = 0) {
    if (this.throttled('rifle', 42)) return;
    this.noiseBurst({ duration: 0.055, gain: 0.055, type: 'bandpass', freq: 1800, q: 0.6, pan });
    this.tone({ freq: 140, endFreq: 48, duration: 0.065, gain: 0.035, pan });
  }

  sniper(pan = 0) {
    this.noiseBurst({ duration: 0.18, gain: 0.13, type: 'bandpass', freq: 1300, q: 0.7, pan, sweep: -900 });
    this.tone({ freq: 95, endFreq: 32, duration: 0.28, gain: 0.09, pan });
  }

  mg(pan = 0) {
    if (this.throttled('mg', 55)) return;
    this.noiseBurst({ duration: 0.045, gain: 0.04, type: 'highpass', freq: 800, q: 0.5, pan });
  }

  cannon(pan = 0) {
    this.noiseBurst({ duration: 0.28, gain: 0.15, type: 'lowpass', freq: 620, q: 0.6, pan, sweep: -420 });
    this.tone({ freq: 78, endFreq: 28, duration: 0.34, gain: 0.16, pan });
  }

  artillery(pan = 0) {
    this.noiseBurst({ duration: 0.42, gain: 0.2, type: 'lowpass', freq: 460, q: 0.5, pan, sweep: -350 });
    this.tone({ freq: 58, endFreq: 24, duration: 0.5, gain: 0.22, pan });
  }

  impact(pan = 0, size = 1) {
    if (this.throttled('impact' + (size > 1.5 ? 'L' : 'S'), 65)) return;
    this.noiseBurst({ duration: 0.22 * size, gain: 0.055 * size, type: 'lowpass', freq: 420, q: 0.5, pan, sweep: -300 });
    this.tone({ freq: 60, endFreq: 28, duration: 0.2 * size, gain: 0.05 * size, pan });
  }

  explosion(pan = 0, size = 1) {
    this.noiseBurst({ duration: 0.55 * size, gain: 0.22 * size, type: 'lowpass', freq: 520, q: 0.7, pan, sweep: -450 });
    this.noiseBurst({ duration: 0.28 * size, gain: 0.09 * size, type: 'bandpass', freq: 2400, q: 0.5, pan, sweep: -1800 });
    this.tone({ freq: 72, endFreq: 21, duration: 0.46 * size, gain: 0.18 * size, pan });
  }

  deploy(pan = 0) {
    this.tone({ freq: 420, endFreq: 680, duration: 0.16, gain: 0.04, type: 'triangle', pan });
    this.noiseBurst({ duration: 0.2, gain: 0.025, type: 'bandpass', freq: 550, q: 0.5, pan });
  }

  ui() {
    this.tone({ freq: 760, endFreq: 920, duration: 0.05, gain: 0.025, type: 'square' });
    this.tone({ freq: 380, endFreq: 410, duration: 0.08, gain: 0.018, type: 'sine', when: 0.03 });
  }

  select() {
    this.tone({ freq: 260, endFreq: 520, duration: 0.08, gain: 0.03, type: 'triangle' });
  }

  deny() {
    this.tone({ freq: 180, endFreq: 110, duration: 0.14, gain: 0.04, type: 'square' });
  }

  alarm() {
    for (let i = 0; i < 2; i++) {
      this.tone({ freq: 620, endFreq: 440, duration: 0.16, gain: 0.035, type: 'sawtooth', when: i * 0.24 });
      this.tone({ freq: 310, endFreq: 240, duration: 0.2, gain: 0.02, type: 'sine', when: i * 0.24 });
    }
  }

  jet() {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.Q.value = 1.2;
    filter.frequency.setValueAtTime(280, t);
    filter.frequency.exponentialRampToValueAtTime(1900, t + 1.2);
    filter.frequency.exponentialRampToValueAtTime(240, t + 2.8);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.13, t + 0.6);
    g.gain.linearRampToValueAtTime(0.04, t + 2.0);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 3.1);
    src.connect(filter).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + 3.2);
  }

  victory() {
    const notes = [220, 277, 330, 440, 554];
    notes.forEach((f, i) => {
      this.tone({ freq: f, endFreq: f * 1.01, duration: 0.55, gain: 0.036, type: 'triangle', when: i * 0.13 });
      this.tone({ freq: f * 0.5, endFreq: f * 0.5, duration: 0.7, gain: 0.018, type: 'sine', when: i * 0.13 });
    });
  }

  defeat() {
    const notes = [220, 196, 164, 110];
    notes.forEach((f, i) => {
      this.tone({ freq: f, endFreq: f * 0.93, duration: 0.8, gain: 0.04, type: 'sawtooth', when: i * 0.22 });
    });
  }
}

@font-face {
  font-family: 'Barlow Condensed';
  src: url('./assets/barlow-condensed-600.woff2') format('woff2');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('./assets/barlow-condensed-700.woff2') format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Barlow Condensed';
  src: url('./assets/barlow-condensed-800.ttf') format('truetype');
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Share Tech Mono';
  src: url('./assets/share-tech-mono.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #080b07;
  --panel: rgba(12, 16, 11, 0.86);
  --panel-solid: #10140e;
  --panel-soft: rgba(23, 29, 19, 0.72);
  --acid: #d7ff4f;
  --acid-soft: #a9ce32;
  --acid-dim: rgba(215, 255, 79, 0.18);
  --amber: #ffb547;
  --enemy: #ff5a3c;
  --text: #f0f4e5;
  --muted: #909b84;
  --muted-2: #606b5a;
  --line: rgba(215, 255, 79, 0.2);
  --line-soft: rgba(236, 244, 221, 0.12);
  --font-display: 'Barlow Condensed', 'Arial Narrow', Impact, sans-serif;
  --font-mono: 'Share Tech Mono', 'Courier New', monospace;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-display);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  overscroll-behavior: none;
}
button { font: inherit; color: inherit; }
button:focus-visible { outline: 2px solid var(--acid); outline-offset: 3px; }
.svg-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; background: #12160e; }
#battlefield {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}
#battlefield.ui-hover { cursor: default; }

.world-fx { position: absolute; inset: 0; pointer-events: none; z-index: 2; }
.vignette {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 32%, rgba(4, 7, 3, 0.28) 74%, rgba(3, 6, 2, 0.74) 100%),
    linear-gradient(180deg, rgba(4, 7, 3, 0.24) 0%, transparent 18%, transparent 74%, rgba(3, 6, 2, 0.4) 100%);
}
.scanlines {
  position: absolute; inset: 0; opacity: 0.14;
  background: repeating-linear-gradient(180deg, transparent 0px, transparent 3px, rgba(2, 5, 1, 0.26) 4px);
  mix-blend-mode: multiply;
}
.grain {
  position: absolute; inset: -30%;
  opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  animation: grainShift 0.8s steps(2) infinite;
}

/* =========================================================================
   Shared micro-elements
   ========================================================================= */
.eyebrow {
  font-family: var(--font-mono);
  font-size: 9px;
  line-height: 1.3;
  letter-spacing: 0.2em;
  color: var(--acid);
  text-transform: uppercase;
}
.micro-label {
  display: block;
  font-family: var(--font-mono);
  font-size: 7.5px;
  line-height: 1.2;
  letter-spacing: 0.14em;
  color: var(--muted);
  white-space: nowrap;
}
.panel-cut {
  background: var(--panel);
  border: 1px solid var(--line-soft);
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 13px 100%, 0 calc(100% - 13px));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.24);
}
.live-dot, .pulse-dot, .status-light {
  display: inline-block;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--acid);
  box-shadow: 0 0 0 4px rgba(215, 255, 79, 0.1), 0 0 12px rgba(215, 255, 79, 0.6);
  animation: dotPulse 1.9s ease-in-out infinite;
}
.live-dot { margin-right: 7px; }
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 17px;
  padding: 0 4px;
  border: 1px solid rgba(236, 244, 221, 0.22);
  background: rgba(255, 255, 255, 0.04);
  color: #dfe7d1;
  font-family: var(--font-mono);
  font-size: 8px;
  line-height: 1;
}
.svg-defs symbol { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* =========================================================================
   HUD
   ========================================================================= */
.hud {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.45s ease, visibility 0.45s;
}
.hud.is-active { opacity: 1; visibility: visible; }

.topbar {
  position: absolute;
  top: calc(14px + var(--safe-top));
  left: 18px;
  right: 18px;
  display: grid;
  grid-template-columns: 258px minmax(280px, 580px) 136px;
  justify-content: space-between;
  align-items: start;
  gap: 18px;
  pointer-events: none;
}
.mission-id { padding: 10px 15px 9px; min-height: 66px; }
.mission-row {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 5px;
}
.mission-row > strong {
  font-family: var(--font-mono);
  font-weight: 400;
  font-size: 21px;
  color: var(--text);
  letter-spacing: 0.01em;
}
.divider { width: 1px; align-self: stretch; background: var(--line-soft); }
.wave-stack b { font-family: var(--font-mono); font-weight: 400; font-size: 16px; color: var(--text); }
.wave-stack .micro-label { margin-bottom: 1px; }

.force-status {
  justify-self: center;
  width: 100%;
  padding: 9px 15px 7px;
}
.force-line {
  display: grid;
  grid-template-columns: 80px 1fr 42px;
  align-items: center;
  gap: 9px;
  height: 17px;
}
.force-line + .force-line { margin-top: 1px; }
.force-name {
  font-family: var(--font-mono);
  font-size: 8.5px;
  letter-spacing: 0.12em;
  color: #dbe3cb;
}
.team-dot {
  display: inline-block;
  width: 5px; height: 5px;
  margin-right: 4px;
  transform: rotate(45deg);
  background: var(--acid);
}
.team-dot.hostile { background: var(--enemy); }
.integritybar {
  height: 5px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.integritybar i {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #8fb92a, var(--acid));
  box-shadow: 0 0 10px rgba(215, 255, 79, 0.35);
  transition: width 0.4s ease;
}
.force-line.hostile .integritybar i {
  background: linear-gradient(90deg, #b63827, var(--enemy));
  box-shadow: 0 0 10px rgba(255, 90, 60, 0.35);
}
.force-line b {
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 400;
  color: var(--muted);
  text-align: right;
}
.force-counts {
  display: flex;
  justify-content: center;
  gap: 7px;
  margin-top: 4px;
  font-family: var(--font-mono);
  font-size: 7.5px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}
.force-counts .vs { color: var(--line); }

.tool-cluster {
  display: flex;
  justify-content: flex-end;
  gap: 5px;
  pointer-events: auto;
}
.icon-button {
  width: 40px;
  height: 40px;
  padding: 0;
  display: grid;
  place-items: center;
  background: var(--panel);
  border: 1px solid var(--line-soft);
  color: #cbd4bd;
  cursor: pointer;
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 0 100%);
  backdrop-filter: blur(12px);
  transition: background 0.18s, color 0.18s, border-color 0.18s;
}
.icon-button:hover { background: rgba(215, 255, 79, 0.12); color: var(--acid); border-color: var(--line); }
.icon-button svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.icon-button.muted { color: var(--muted-2); }

.objective {
  position: absolute;
  top: 108px;
  left: 18px;
  width: 256px;
  padding: 13px 15px 12px;
  pointer-events: none;
}
.objective-title {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 6px;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.objective-title svg { width: 17px; height: 17px; color: var(--acid); fill: none; stroke: currentColor; stroke-width: 1.7; }
.objective p {
  margin: 5px 0 12px;
  max-width: 210px;
  color: #a7b09b;
  font-family: var(--font-mono);
  font-size: 8.5px;
  line-height: 1.55;
  letter-spacing: 0.02em;
}
.objective-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
}
.objective-meta b { color: var(--text); font-weight: 400; }
.objective-track { height: 3px; background: rgba(255, 255, 255, 0.08); margin-top: 6px; }
.objective-track i { display: block; height: 100%; width: 100%; background: var(--acid); transition: width 0.4s; }

.wave-banner {
  position: absolute;
  top: 116px;
  left: 50%;
  transform: translate(-50%, -12px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding: 10px 34px 9px;
  background: linear-gradient(90deg, transparent, rgba(7, 11, 6, 0.94) 18%, rgba(7, 11, 6, 0.94) 82%, transparent);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s, transform 0.3s, visibility 0.3s;
  pointer-events: none;
}
.wave-banner.show { opacity: 1; visibility: visible; transform: translate(-50%, 0); }
.wave-banner::before, .wave-banner::after {
  content: "";
  position: absolute;
  top: 0; bottom: 0;
  width: 1px;
  background: var(--acid);
  opacity: 0.7;
}
.wave-banner::before { left: 0; }
.wave-banner::after { right: 0; }
.wave-kicker { font-family: var(--font-mono); font-size: 7.5px; letter-spacing: 0.34em; color: var(--enemy); }
.wave-banner strong { font-size: 30px; font-weight: 800; letter-spacing: 0.14em; line-height: 1; }
.wave-sub { font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.16em; color: var(--muted); margin-top: 3px; }

.toast-stack {
  position: absolute;
  top: 112px;
  right: 18px;
  width: 280px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
  pointer-events: none;
}
.toast {
  width: 100%;
  padding: 8px 11px 8px 13px;
  background: rgba(9, 13, 8, 0.9);
  border: 1px solid var(--line-soft);
  border-left: 2px solid var(--acid);
  color: #c9d3ba;
  font-family: var(--font-mono);
  font-size: 8px;
  line-height: 1.5;
  letter-spacing: 0.035em;
  backdrop-filter: blur(10px);
  animation: toastIn 0.25s ease both;
}
.toast.warn { border-left-color: var(--amber); color: #f4d59d; }
.toast.bad { border-left-color: var(--enemy); color: #ffb7a9; }
.toast.out { animation: toastOut 0.3s ease forwards; }

.kill-feed {
  position: absolute;
  left: 18px;
  bottom: 164px;
  width: 230px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-family: var(--font-mono);
  font-size: 7.5px;
  letter-spacing: 0.06em;
  color: var(--muted-2);
  pointer-events: none;
}
.kill-feed div {
  padding: 2px 6px;
  background: linear-gradient(90deg, rgba(7, 10, 6, 0.58), transparent);
  animation: feedIn 0.2s ease both;
}
.kill-feed b { color: var(--acid-soft); font-weight: 400; }
.kill-feed .hostile b { color: var(--enemy); }

/* =========================================================================
   Command bar
   ========================================================================= */
.commandbar {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: calc(14px + var(--safe-bottom));
  display: grid;
  grid-template-columns: 194px minmax(0, 1fr) 204px;
  align-items: stretch;
  gap: 9px;
  pointer-events: none;
}
.commandbar > * { pointer-events: auto; }
.cp-block {
  padding: 10px 13px 9px;
  background: var(--panel);
  border: 1px solid var(--line-soft);
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 0 100%);
  backdrop-filter: blur(14px);
}
.cp-top { display: flex; align-items: center; justify-content: space-between; }
.cp-income { font-family: var(--font-mono); font-size: 8px; color: var(--muted); }
.cp-income b { color: var(--acid); font-weight: 400; }
.cp-readout { display: flex; align-items: baseline; gap: 4px; margin-top: 2px; }
.cp-readout strong { font-family: var(--font-mono); font-size: 36px; font-weight: 400; line-height: 1; color: var(--text); }
.cp-readout span { font-family: var(--font-mono); font-size: 10px; color: var(--muted-2); }
.cp-track { position: relative; height: 6px; margin-top: 5px; background: rgba(255, 255, 255, 0.08); overflow: hidden; }
.cp-track > i {
  display: block; height: 100%; width: 60%;
  background: linear-gradient(90deg, #7fa41f, var(--acid));
  box-shadow: 0 0 12px rgba(215, 255, 79, 0.32);
  transition: width 0.2s linear;
}
.cp-ticks {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(6, 9, 4, 0.7) calc(10% - 1px), rgba(6, 9, 4, 0.7) 10%);
}
.cp-note { margin-top: 6px; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: 0.08em; color: var(--muted-2); white-space: nowrap; }
.pulse-dot { width: 4px; height: 4px; margin-right: 4px; box-shadow: none; animation-duration: 1.4s; vertical-align: 1px; }

.tray-block {
  min-width: 0;
  padding: 7px 8px 8px;
  background: var(--panel);
  border: 1px solid var(--line-soft);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 0 100%);
  backdrop-filter: blur(14px);
}
.tray-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 3px 5px;
  font-family: var(--font-mono);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  color: var(--muted-2);
}
#selectionHint { color: var(--muted); transition: color 0.2s; }
#selectionHint.active { color: var(--acid); }
.unit-tray { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px; }

.unit-card {
  position: relative;
  height: 88px;
  min-width: 0;
  padding: 6px 3px 5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 0;
  border: 1px solid rgba(236, 244, 221, 0.11);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), transparent 40%),
    rgba(21, 28, 18, 0.82);
  clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 0 100%);
  color: var(--text);
  cursor: pointer;
  overflow: hidden;
  transition: border-color 0.16s, background 0.16s, transform 0.16s;
}
.unit-card:hover {
  transform: translateY(-2px);
  border-color: rgba(215, 255, 79, 0.55);
  background: linear-gradient(180deg, rgba(215, 255, 79, 0.12), transparent 55%), rgba(25, 33, 20, 0.92);
}
.unit-card.selected {
  border-color: var(--acid);
  background: linear-gradient(180deg, rgba(215, 255, 79, 0.2), transparent 65%), rgba(31, 41, 23, 0.96);
  box-shadow: inset 0 -2px 0 var(--acid), 0 0 24px rgba(215, 255, 79, 0.16);
}
.unit-card.selected .unit-icon { color: var(--acid); filter: drop-shadow(0 0 6px rgba(215, 255, 79, 0.4)); }
.unit-card.disabled { opacity: 0.42; cursor: not-allowed; filter: saturate(0.4); }
.unit-card.disabled:hover { transform: none; border-color: rgba(236, 244, 221, 0.11); }
.unit-icon { width: 33px; height: 33px; margin-bottom: 3px; color: #d4ddc4; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; transition: color 0.16s; flex: 0 0 auto; }
.unit-name { font-size: 12.5px; font-weight: 700; letter-spacing: 0.055em; line-height: 1.05; white-space: nowrap; }
.unit-role { font-family: var(--font-mono); font-size: 5.8px; letter-spacing: 0.1em; color: var(--muted-2); margin-top: 2px; white-space: nowrap; }
.hotkey {
  position: absolute; left: 4px; top: 3px;
  font-family: var(--font-mono); font-size: 6.5px; color: var(--muted-2);
}
.cost {
  position: absolute; right: 0; top: 0;
  min-width: 22px; padding: 3px 4px 4px;
  background: var(--acid);
  color: #11150b;
  font-family: var(--font-mono);
  font-size: 9px;
  line-height: 1;
  text-align: center;
  clip-path: polygon(0 0, 100% 0, 100% 100%, 5px 100%);
}
.cost span { font-size: 5px; margin-left: 1px; opacity: 0.7; }
.support-card .cost { background: var(--amber); }
.support-card .unit-icon { color: #ffd58f; }
.support-card.selected .unit-icon { color: var(--amber); filter: drop-shadow(0 0 6px rgba(255, 181, 71, 0.45)); }
.support-card:hover { border-color: rgba(255, 181, 71, 0.6); background: linear-gradient(180deg, rgba(255, 181, 71, 0.12), transparent 55%), rgba(25, 33, 20, 0.92); }
.card-scan {
  position: absolute; left: -30%; top: -20%; width: 30%; height: 140%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.1), transparent);
  transform: skewX(-18deg);
  opacity: 0;
  transition: left 0.45s ease, opacity 0.2s;
  pointer-events: none;
}
.unit-card:hover .card-scan { left: 120%; opacity: 1; }
.cooldown-mask {
  position: absolute; inset: 0;
  background: rgba(5, 8, 4, 0.74);
  transform-origin: bottom;
  transform: scaleY(0);
  pointer-events: none;
  transition: transform 0.12s linear;
}
.cooldown-text {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  font-family: var(--font-mono); font-size: 11px; color: #ffd58f;
  text-shadow: 0 1px 4px #000;
  pointer-events: none;
}

.tactical-block {
  padding: 10px 12px 9px;
  background: var(--panel);
  border: 1px solid var(--line-soft);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  backdrop-filter: blur(14px);
}
.tactical-block p {
  margin: 5px 0 8px;
  font-family: var(--font-mono);
  font-size: 7.5px;
  line-height: 1.5;
  color: #a2ad94;
}
.control-hints { display: flex; flex-wrap: wrap; gap: 4px 8px; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: 0.06em; color: var(--muted-2); }
.control-hints span { display: flex; align-items: center; gap: 3px; white-space: nowrap; }
.control-hints kbd { min-width: 15px; height: 14px; font-size: 6px; padding: 0 3px; }

.deploy-disc { display: none; }

/* =========================================================================
   Start screen
   ========================================================================= */
.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: none;
}
.screen.is-active { display: flex; }
.start-screen {
  flex-direction: column;
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(6, 9, 5, 0.97) 0%, rgba(6, 9, 5, 0.9) 32%, rgba(6, 9, 5, 0.22) 64%, rgba(5, 8, 4, 0.66) 100%),
    radial-gradient(ellipse at 72% 45%, rgba(38, 48, 27, 0.1), transparent 60%),
    linear-gradient(180deg, rgba(4, 7, 3, 0.5), transparent 22%, transparent 78%, rgba(3, 5, 2, 0.8));
}
.start-screen::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 48%;
  background: linear-gradient(90deg, rgba(6, 9, 5, 0.82), transparent);
  pointer-events: none;
}
.start-noise {
  position: absolute; inset: 0; pointer-events: none; opacity: 0.1;
  background-image:
    linear-gradient(rgba(215, 255, 79, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(215, 255, 79, 0.04) 1px, transparent 1px);
  background-size: 68px 68px;
  mask-image: linear-gradient(90deg, #000, transparent 54%);
}
.start-top {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  padding: calc(24px + var(--safe-top)) 38px 0;
  font-family: var(--font-mono);
  font-size: 8.5px;
  letter-spacing: 0.16em;
  color: var(--muted);
}
.brand { display: flex; align-items: center; gap: 9px; color: #e4ebd6; }
.brand b { color: var(--acid); font-weight: 400; }
.brand-mark {
  display: grid; place-items: center;
  width: 27px; height: 27px;
  border: 1px solid rgba(215, 255, 79, 0.45);
  background: rgba(215, 255, 79, 0.08);
  transform: rotate(45deg);
}
.brand-mark svg { width: 15px; height: 15px; transform: rotate(-45deg); fill: none; stroke: var(--acid); stroke-width: 1.7; }
.start-top-right { display: flex; align-items: center; gap: 9px; color: var(--muted); }
.build { padding-left: 12px; margin-left: 4px; border-left: 1px solid var(--line-soft); color: var(--muted-2); }

.start-grid {
  position: relative;
  z-index: 2;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(280px, 0.5fr);
  align-items: center;
  gap: 50px;
  width: 100%;
  max-width: 1560px;
  margin: 0 auto;
  padding: 20px 52px 76px 64px;
}
.start-copy { max-width: 830px; animation: revealUp 0.8s 0.1s ease both; }
.kicker {
  display: flex; align-items: center; gap: 12px;
  font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.22em; color: var(--acid);
  margin-bottom: 18px;
}
.kicker i { display: block; width: 38px; height: 1px; background: var(--acid); opacity: 0.55; }
h1 {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(108px, 13vw, 206px);
  line-height: 0.71;
  letter-spacing: -0.015em;
  text-transform: uppercase;
  display: flex;
  flex-direction: column;
  text-shadow: 0 10px 60px rgba(0, 0, 0, 0.45);
}
h1 > span { display: block; }
h1 .outline {
  color: transparent;
  -webkit-text-stroke: 2px rgba(235, 243, 219, 0.58);
  letter-spacing: 0.015em;
  padding-bottom: 0.12em;
}
.subtitle {
  margin-top: 10px;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.52em;
  color: var(--acid);
}
.lead {
  max-width: 535px;
  margin: 23px 0 24px;
  color: #adb6a0;
  font-family: var(--font-mono);
  font-size: 10.5px;
  line-height: 1.8;
  letter-spacing: 0.02em;
}
.mission-brief {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  max-width: 660px;
  margin-bottom: 26px;
}
.brief-item {
  display: flex;
  gap: 9px;
  padding-top: 9px;
  border-top: 1px solid rgba(236, 244, 221, 0.14);
}
.brief-item > span { font-family: var(--font-mono); font-size: 8px; color: var(--acid); padding-top: 2px; }
.brief-item b { display: block; font-size: 13.5px; letter-spacing: 0.07em; color: #dce4cd; }
.brief-item small { display: block; margin-top: 3px; font-family: var(--font-mono); font-size: 7px; line-height: 1.5; color: var(--muted-2); }
.start-actions { display: flex; align-items: stretch; gap: 9px; }
.primary-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 0 24px 0 9px;
  height: 61px;
  min-width: 258px;
  border: 0;
  background: var(--acid);
  color: #10140a;
  clip-path: polygon(0 0, calc(100% - 15px) 0, 100% 15px, 100% 100%, 0 100%);
  cursor: pointer;
  overflow: hidden;
  transition: background 0.16s, transform 0.16s;
}
.primary-btn:hover { background: #e3ff7d; transform: translateY(-1px); }
.primary-btn:active { transform: translateY(0); }
.btn-icon {
  display: grid; place-items: center;
  width: 43px; height: 43px;
  background: rgba(11, 15, 7, 0.12);
  flex: 0 0 auto;
}
.btn-icon svg { width: 18px; height: 18px; fill: currentColor; stroke: none; }
.btn-copy { display: flex; flex-direction: column; align-items: flex-start; line-height: 1; }
.btn-copy b { font-size: 18px; font-weight: 800; letter-spacing: 0.1em; }
.btn-copy small { margin-top: 4px; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.12em; opacity: 0.58; }
.btn-bar { position: absolute; left: 0; bottom: 0; width: 0; height: 2px; background: #fff; animation: btnLoad 2.4s ease-in-out infinite; }
.ghost-btn {
  height: 61px;
  padding: 0 19px;
  border: 1px solid rgba(236, 244, 221, 0.24);
  background: rgba(8, 12, 7, 0.3);
  color: #c7d0b8;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.13em;
  cursor: pointer;
  transition: border-color 0.16s, color 0.16s, background 0.16s;
}
.ghost-btn:hover { border-color: var(--acid); color: var(--acid); background: rgba(215, 255, 79, 0.06); }
.start-hints { display: flex; gap: 10px; margin-top: 17px; font-family: var(--font-mono); font-size: 6.8px; letter-spacing: 0.12em; color: var(--muted-2); }
.hint-sep { color: rgba(215, 255, 79, 0.22); }

.intel-panel {
  align-self: end;
  width: 100%;
  max-width: 340px;
  justify-self: end;
  background: rgba(9, 13, 8, 0.78);
  border: 1px solid rgba(215, 255, 79, 0.16);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  padding: 14px;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 0 100%);
  animation: revealUp 0.8s 0.28s ease both;
}
.intel-head {
  display: flex; justify-content: space-between;
  padding-bottom: 9px; border-bottom: 1px solid var(--line-soft);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: 0.16em; color: var(--acid);
}
.intel-code { color: var(--muted-2); }
.radar {
  position: relative;
  height: 148px;
  margin: 12px 0;
  overflow: hidden;
  background:
    radial-gradient(circle at center, rgba(215, 255, 79, 0.06), transparent 62%),
    rgba(4, 7, 3, 0.58);
  border: 1px solid rgba(215, 255, 79, 0.13);
}
.radar-grid {
  position: absolute; inset: 0;
  background:
    linear-gradient(rgba(215, 255, 79, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(215, 255, 79, 0.08) 1px, transparent 1px);
  background-size: 24px 24px;
  mask-image: radial-gradient(circle at center, #000 30%, transparent 76%);
}
.radar::before, .radar::after {
  content: ""; position: absolute; border: 1px solid rgba(215, 255, 79, 0.16); border-radius: 50%;
  left: 50%; top: 50%; transform: translate(-50%, -50%);
}
.radar::before { width: 116px; height: 116px; }
.radar::after { width: 70px; height: 70px; }
.radar-sweep {
  position: absolute; left: 50%; top: 50%; width: 145px; height: 145px;
  transform-origin: 0 0;
  background: conic-gradient(from 0deg, rgba(215, 255, 79, 0.3), transparent 42deg);
  animation: radarSpin 4.2s linear infinite;
  clip-path: circle(72px at 0 0);
  opacity: 0.75;
}
.radar-cross { position: absolute; left: 50%; top: 0; bottom: 0; width: 1px; background: rgba(215, 255, 79, 0.08); }
.radar-label { position: absolute; left: 8px; bottom: 6px; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: 0.12em; color: var(--muted-2); }
.blip { position: absolute; width: 5px; height: 5px; background: var(--enemy); transform: rotate(45deg); box-shadow: 0 0 8px var(--enemy); animation: blipPulse 2.4s ease-in-out infinite; }
.blip.b1 { left: 61%; top: 31%; }
.blip.b2 { left: 72%; top: 64%; animation-delay: 0.4s; }
.blip.b3 { left: 43%; top: 73%; animation-delay: 0.9s; }
.blip.b4 { left: 34%; top: 42%; animation-delay: 1.4s; background: var(--acid); box-shadow: 0 0 8px var(--acid); }
.intel-row {
  display: grid; grid-template-columns: 62px 1fr 36px; align-items: center; gap: 6px;
  padding: 6px 0; border-bottom: 1px solid rgba(236, 244, 221, 0.07);
  font-family: var(--font-mono); font-size: 7.6px;
}
.threat-tag { color: var(--muted-2); letter-spacing: 0.08em; }
.intel-row b { color: #d6dfc8; font-weight: 400; letter-spacing: 0.03em; }
.threat-level { font-size: 6.5px; text-align: right; letter-spacing: 0.06em; }
.threat-level.high { color: var(--enemy); }
.threat-level.med { color: var(--amber); }
.threat-level.low { color: var(--acid); }
.intel-footer { display: flex; justify-content: space-between; margin-top: 11px; font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.1em; color: var(--muted-2); }
.intel-footer b { color: var(--acid); font-weight: 400; }

.start-footer {
  position: absolute; left: 38px; right: 38px; bottom: calc(19px + var(--safe-bottom));
  z-index: 2;
  display: flex; justify-content: space-between; align-items: center;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.12em; color: var(--muted-2);
  padding-top: 10px; border-top: 1px solid rgba(236, 244, 221, 0.09);
}
.start-footer > div { display: flex; align-items: center; gap: 7px; }
.status-light { width: 4px; height: 4px; box-shadow: none; }
.start-coords { color: rgba(215, 255, 79, 0.46); }

/* =========================================================================
   Modals / help / pause
   ========================================================================= */
.modal-screen {
  align-items: center;
  justify-content: center;
  padding: 22px;
  background: rgba(4, 7, 3, 0.76);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
}
.modal-panel {
  width: min(980px, 100%);
  max-height: min(92vh, 780px);
  overflow: auto;
  padding: 22px;
  background: #0e120c;
  border: 1px solid rgba(215, 255, 79, 0.18);
  box-shadow: 0 30px 120px rgba(0, 0, 0, 0.6);
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 0 100%);
  animation: revealUp 0.3s ease both;
}
.modal-head { display: flex; justify-content: space-between; align-items: flex-start; padding-bottom: 16px; border-bottom: 1px solid var(--line-soft); }
.modal-head h2 { margin: 5px 0 0; font-size: 42px; line-height: 0.9; letter-spacing: 0.02em; font-weight: 800; }
.close-button {
  width: 38px; height: 38px;
  border: 1px solid var(--line-soft);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-family: var(--font-mono);
  font-size: 13px;
  transition: color 0.16s, border-color 0.16s;
}
.close-button:hover { color: var(--acid); border-color: var(--acid); }
.manual-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 17px; }
.manual-card {
  position: relative;
  padding: 13px 13px 11px;
  border: 1px solid rgba(236, 244, 221, 0.1);
  background: rgba(255, 255, 255, 0.022);
  min-height: 168px;
}
.manual-card svg { width: 34px; height: 34px; color: var(--acid); fill: none; stroke: currentColor; stroke-width: 1.7; margin-bottom: 8px; }
.manual-card h3 { margin: 0; font-size: 19px; letter-spacing: 0.06em; }
.manual-card p { margin: 5px 0 12px; font-family: var(--font-mono); font-size: 7.5px; line-height: 1.6; color: var(--muted); }
.manual-num { position: absolute; right: 9px; top: 8px; font-family: var(--font-mono); font-size: 8px; color: var(--muted-2); }
.statline { font-family: var(--font-mono); font-size: 6.8px; letter-spacing: 0.06em; color: var(--acid-soft); }
.manual-air { border-color: rgba(255, 181, 71, 0.28); background: rgba(255, 181, 71, 0.035); }
.manual-air svg, .manual-air .statline { color: var(--amber); }
.manual-controls { display: flex; flex-wrap: wrap; gap: 18px; margin-top: 17px; padding-top: 14px; border-top: 1px solid var(--line-soft); font-family: var(--font-mono); font-size: 7.5px; color: var(--muted); }
.manual-controls > div { display: flex; align-items: center; gap: 4px; }
.manual-controls span { margin-left: 4px; color: var(--muted-2); }

.pause-panel {
  width: min(430px, 100%);
  padding: 30px;
  text-align: center;
  background: var(--panel-solid);
  border: 1px solid var(--line);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 0 100%);
  animation: revealUp 0.28s ease both;
}
.pause-panel h2 { margin: 6px 0 0; font-size: 76px; font-weight: 800; line-height: 0.85; }
.pause-panel p { margin: 11px 0 21px; font-family: var(--font-mono); font-size: 8.5px; line-height: 1.6; color: var(--muted); }
.primary-btn.compact { min-width: 0; width: 100%; justify-content: flex-start; }
.pause-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 8px; }
.pause-actions .ghost-btn { height: 44px; }

/* =========================================================================
   Result screen
   ========================================================================= */
.result-screen {
  align-items: center;
  justify-content: flex-start;
  padding: 5vh 7vw;
  background:
    linear-gradient(90deg, rgba(5, 8, 4, 0.97), rgba(5, 8, 4, 0.84) 55%, rgba(5, 8, 4, 0.4)),
    radial-gradient(ellipse at 75% 50%, rgba(255, 90, 60, 0.08), transparent 55%);
  overflow: hidden;
}
.result-screen.victory { background: linear-gradient(90deg, rgba(5, 8, 4, 0.97), rgba(5, 8, 4, 0.75) 55%, rgba(5, 8, 4, 0.35)), radial-gradient(ellipse at 74% 48%, rgba(215, 255, 79, 0.09), transparent 56%); }
.result-ribbon {
  position: absolute; top: 8vh; left: 0;
  padding: 8px 18vw 8px 7vw;
  background: var(--acid);
  color: #10140b;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  clip-path: polygon(0 0, 100% 0, calc(100% - 16px) 100%, 0 100%);
}
.result-screen.defeat .result-ribbon { background: var(--enemy); }
.result-main { max-width: 880px; animation: revealUp 0.6s ease both; position: relative; z-index: 2; }
.result-main h2 {
  margin: 10px 0 0;
  font-size: clamp(96px, 14vw, 196px);
  font-weight: 800;
  line-height: 0.76;
  letter-spacing: -0.01em;
  color: var(--acid);
  text-shadow: 0 0 80px rgba(215, 255, 79, 0.12);
}
.result-screen.defeat .result-main h2 { color: var(--enemy); text-shadow: 0 0 80px rgba(255, 90, 60, 0.12); }
.result-main > p { max-width: 470px; margin: 18px 0 27px; font-family: var(--font-mono); font-size: 10px; line-height: 1.7; color: var(--muted); }
.result-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; max-width: 700px; background: rgba(236, 244, 221, 0.1); border: 1px solid rgba(236, 244, 221, 0.1); margin-bottom: 25px; }
.result-stats > div { padding: 13px 14px; background: rgba(10, 14, 8, 0.86); }
.result-stats span { display: block; font-family: var(--font-mono); font-size: 6.8px; letter-spacing: 0.1em; color: var(--muted-2); }
.result-stats b { display: block; margin-top: 4px; font-family: var(--font-mono); font-size: 24px; font-weight: 400; color: var(--text); }
.result-actions { display: flex; gap: 9px; }
.result-stamp {
  position: absolute;
  right: 4vw;
  bottom: 8vh;
  padding: 9px 18px;
  border: 2px solid rgba(215, 255, 79, 0.45);
  color: rgba(215, 255, 79, 0.5);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  transform: rotate(-7deg);
}
.result-screen.defeat .result-stamp { border-color: rgba(255, 90, 60, 0.4); color: rgba(255, 90, 60, 0.56); }
.rotate-hint { display: none; }

/* =========================================================================
   Animations
   ========================================================================= */
@keyframes dotPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
@keyframes grainShift { 0% { transform: translate(0, 0); } 25% { transform: translate(2%, -1%); } 50% { transform: translate(-1%, 2%); } 75% { transform: translate(1%, 1%); } 100% { transform: translate(-2%, -1%); } }
@keyframes radarSpin { to { transform: rotate(360deg); } }
@keyframes blipPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
@keyframes revealUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
@keyframes btnLoad { 0% { width: 0; opacity: 0; } 30% { opacity: 0.65; } 100% { width: 100%; opacity: 0; } }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } to { opacity: 1; transform: translateX(0); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(18px); } }
@keyframes feedIn { from { opacity: 0; transform: translateX(-10px); } to { opacity: 1; transform: translateX(0); } }
@keyframes hitPulse { 0% { opacity: 0.42; } 100% { opacity: 0; } }

#app.hit::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 42%, rgba(255, 62, 37, 0.3));
  animation: hitPulse 0.42s ease-out forwards;
}

